INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_edumic_1792151537397","EduMic","Operating System: Other","# EduMic\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nEduMic is a versatile hearing aid accessory. In remote microphone mode, it helps you when distance and noise make it difficult to hear the person speaking – in the classroom, in work situations, during sports, and more. EduMic can also plug in to devices via a standard 3.5mm headphone jack, to stream audio wirelessly to Oticon Bluetooth hearing aids. It also picks up audio from public hearing loop systems.\n\nManufacturer: Oticon (https://www.oticon.global/hearing-aid-users)\n\nEduMic Support: https://www.oticon.com/support/how-to/use-edumic\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/edumic/","MADA Portal","web","https://at.mada.org.qa/technology/edumic/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Oticon-EduMic.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Oticon-EduMic.png\"]}",0,NULL,NULL,"2026-10-16T11:52:17.397Z","2026-10-16T11:52:17.397Z","EduMic","","","Operating System: Other",NULL,NULL,"# EduMic\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nEduMic is a versatile hearing aid accessory. In remote microphone mode, it helps you when distance and noise make it difficult to hear the person speaking – in the classroom, in work situations, during sports, and more. EduMic can also plug in to devices via a standard 3.5mm headphone jack, to stream audio wirelessly to Oticon Bluetooth hearing aids. It also picks up audio from public hearing loop systems.\n\nManufacturer: Oticon (https://www.oticon.global/hearing-aid-users)\n\nEduMic Support: https://www.oticon.com/support/how-to/use-edumic\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/edumic/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_oticon-amigo-t31-t30_1792151539433","Oticon Amigo T31, T30","Operating System: Other","# Oticon Amigo T31, T30\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nTeachers want to spend their time teaching – not trying to decipher complex FM systems. Amigo transmitters make life easy. They simply turn on the transmitter, clip on the microphone and begin teaching. The transmitters send the teacher’s voice directly to the pupil, overcoming the effects of noise, distance and reverberation that can make it hard for children to hear.\nThere’s always lots of activity taking place in a classroom, and background noise in any form can be extremely distracting to children – but particularly to those with listening difficulties.\nAmigo Star has the ability to help children conserve some of their resources to concentrate on what matters most: their learning.\nAmigo Star is the latest evolution of the Amigo FM family – designed to help normal hearing children with listening difficulties concentrate better in class.\n• Smooth integration: integrates with the Amigo FM system or any FM system already in place\n• Comfortable and discreet: available in a range of colours with tubes and domes in various sizes\n• Easy and intuitive to use: fit it to the ear, switch on, sync and start\n• Robust: drop- and water- resistant\n\nUser Support: https://www.oticon.com/-/media/oticon-us/main/download-center/amigo/ifu/108616us-instructions-for-use—amigo-t30-t31.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/oticon-amigo-t31-t30/","MADA Portal","web","https://at.mada.org.qa/technology/oticon-amigo-t31-t30/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Oticon-Amigo-T31T30.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Oticon-Amigo-T31T30.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:19.433Z","2026-10-16T11:52:19.433Z","Oticon Amigo T31, T30","","","Operating System: Other",NULL,NULL,"# Oticon Amigo T31, T30\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nTeachers want to spend their time teaching – not trying to decipher complex FM systems. Amigo transmitters make life easy. They simply turn on the transmitter, clip on the microphone and begin teaching. The transmitters send the teacher’s voice directly to the pupil, overcoming the effects of noise, distance and reverberation that can make it hard for children to hear.\nThere’s always lots of activity taking place in a classroom, and background noise in any form can be extremely distracting to children – but particularly to those with listening difficulties.\nAmigo Star has the ability to help children conserve some of their resources to concentrate on what matters most: their learning.\nAmigo Star is the latest evolution of the Amigo FM family – designed to help normal hearing children with listening difficulties concentrate better in class.\n• Smooth integration: integrates with the Amigo FM system or any FM system already in place\n• Comfortable and discreet: available in a range of colours with tubes and domes in various sizes\n• Easy and intuitive to use: fit it to the ear, switch on, sync and start\n• Robust: drop- and water- resistant\n\nUser Support: https://www.oticon.com/-/media/oticon-us/main/download-center/amigo/ifu/108616us-instructions-for-use—amigo-t30-t31.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/oticon-amigo-t31-t30/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_streamline-mic_1792151541646","StreamLine Mic","Operating System: Windows, iOS, Android, Chrome","# StreamLine Mic\n\n## Mô tả\nOperating System: Windows, iOS, Android, Chrome\n\n## Chi tiết sản phẩm\nThe StreamLine Mic provides full hands-free audio streaming of phone calls and music from any Bluethooth device in stereo quality. They also become a hands-free mobile headset and wireless headphones that stream premium stereo quality from any Bluetooth device – smart assistants like Alexa, Siri and Google Assistant.\n\nManufacturer: Signia (https://www.signia.net/en/chargers-and-accessories/streamline-mic/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/streamline-mic/","MADA Portal","web","https://at.mada.org.qa/technology/streamline-mic/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/StreamLine-Mic.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/StreamLine-Mic.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:21.646Z","2026-10-16T11:52:21.646Z","StreamLine Mic","","","Operating System: Windows, iOS, Android, Chrome",NULL,NULL,"# StreamLine Mic\n\n## Mô tả\nOperating System: Windows, iOS, Android, Chrome\n\n## Chi tiết sản phẩm\nThe StreamLine Mic provides full hands-free audio streaming of phone calls and music from any Bluethooth device in stereo quality. They also become a hands-free mobile headset and wireless headphones that stream premium stereo quality from any Bluetooth device – smart assistants like Alexa, Siri and Google Assistant.\n\nManufacturer: Signia (https://www.signia.net/en/chargers-and-accessories/streamline-mic/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/streamline-mic/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_signia-streamline-tv-connector_1792151543726","Signia Streamline TV Connector","Operating System: iOS, Android, Other","# Signia Streamline TV Connector\n\n## Mô tả\nOperating System: iOS, Android, Other\n\n## Chi tiết sản phẩm\nThe Signia Streamline TV is built for user ease in mind. Once connected to the StreamLine TV you will get seamless streaming for your TV programs without any hassle. With control of the volume directly through the Signia App you will have full control of what and how you hear.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/signia-streamline-tv-connector/","MADA Portal","web","https://at.mada.org.qa/technology/signia-streamline-tv-connector/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/StreamLine-TV-Connector.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/StreamLine-TV-Connector.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:23.726Z","2026-10-16T11:52:23.726Z","Signia Streamline TV Connector","","","Operating System: iOS, Android, Other",NULL,NULL,"# Signia Streamline TV Connector\n\n## Mô tả\nOperating System: iOS, Android, Other\n\n## Chi tiết sản phẩm\nThe Signia Streamline TV is built for user ease in mind. Once connected to the StreamLine TV you will get seamless streaming for your TV programs without any hassle. With control of the volume directly through the Signia App you will have full control of what and how you hear.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/signia-streamline-tv-connector/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_resound-tv-streamer-2_1792151545606","ReSound TV streamer 2","Operating System: Other","# ReSound TV streamer 2\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nWith the ReSound TV Streamer 2, you can enjoy watching TV with your friends and family again.The  ReSound TV Streamer 2 allows you stream crystal-clear stereo sound from the television straight to your hearing aids, which gives you confidence knowing you will hear every word. Meanwhile, your friends and family can listen at a comfortable volume.\n\nManufacturer: ReSound (https://www.resound.com/en-us/hearing-aids/accessories/tv-hearing-aid)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/resound-tv-streamer-2/","MADA Portal","web","https://at.mada.org.qa/technology/resound-tv-streamer-2/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/resound-tv-streamer.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/resound-tv-streamer.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:25.606Z","2026-10-16T11:52:25.606Z","ReSound TV streamer 2","","","Operating System: Other",NULL,NULL,"# ReSound TV streamer 2\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nWith the ReSound TV Streamer 2, you can enjoy watching TV with your friends and family again.The  ReSound TV Streamer 2 allows you stream crystal-clear stereo sound from the television straight to your hearing aids, which gives you confidence knowing you will hear every word. Meanwhile, your friends and family can listen at a comfortable volume.\n\nManufacturer: ReSound (https://www.resound.com/en-us/hearing-aids/accessories/tv-hearing-aid)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/resound-tv-streamer-2/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_radiolink-universal-receiver_1792151547691","IQstream TV","Operating System: Other","# IQstream TV\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nTV streamers are devices that you can connect to your TV set which will send the audio directly to your hearing aids. They need to be compatible with your type of hearing aid.\n\nIQstream TV streams clear stereo sound from the TV to users’ IQbuds MAX or IQbuds BOOST earbuds so you can enjoy TV audio at the volume you want while others can listen at the volume they prefer.\n\nManufacturer: Nuheara (https://www.nuheara.com/au/products/iqstream-tv/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/radiolink-universal-receiver/","MADA Portal","web","https://at.mada.org.qa/technology/radiolink-universal-receiver/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/IQStream-TV.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/IQStream-TV.png\"]}",0,NULL,NULL,"2026-10-16T11:52:27.691Z","2026-10-16T11:52:27.691Z","IQstream TV","","","Operating System: Other",NULL,NULL,"# IQstream TV\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nTV streamers are devices that you can connect to your TV set which will send the audio directly to your hearing aids. They need to be compatible with your type of hearing aid.\n\nIQstream TV streams clear stereo sound from the TV to users’ IQbuds MAX or IQbuds BOOST earbuds so you can enjoy TV audio at the volume you want while others can listen at the volume they prefer.\n\nManufacturer: Nuheara (https://www.nuheara.com/au/products/iqstream-tv/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/radiolink-universal-receiver/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_echo-2-4g-wireless-neckloop-system_1792151549726","Echo® 2.4G Wireless Neckloop System","Operating System: Other","# Echo® 2.4G Wireless Neckloop System\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nEcho® 2.4G Wireless Neckloop System is a TV listeners that you listen to your TV at a volume you are comfortable with at the same time as the TV speaker. Echo NEW Echo® 2.4G wireless digital TV listening system uses 2.4GHz transmission technology to transmit sound from TV (or other sound sources) to a neckloop receiver.\n\nManufacturer: Hearing Products International Ltd. (https://www.hear4you.com/)\n\nUser Manual: https://www.hear4you.com/wp-content/uploads/2021/02/ECHO-2.4G-manual202001120%EF%BC%89.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/echo-2-4g-wireless-neckloop-system/","MADA Portal","web","https://at.mada.org.qa/technology/echo-2-4g-wireless-neckloop-system/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Echo_2-4G_NeckLoop3.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Echo_2-4G_NeckLoop3.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:29.727Z","2026-10-16T11:52:29.727Z","Echo® 2.4G Wireless Neckloop System","","","Operating System: Other",NULL,NULL,"# Echo® 2.4G Wireless Neckloop System\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nEcho® 2.4G Wireless Neckloop System is a TV listeners that you listen to your TV at a volume you are comfortable with at the same time as the TV speaker. Echo NEW Echo® 2.4G wireless digital TV listening system uses 2.4GHz transmission technology to transmit sound from TV (or other sound sources) to a neckloop receiver.\n\nManufacturer: Hearing Products International Ltd. (https://www.hear4you.com/)\n\nUser Manual: https://www.hear4you.com/wp-content/uploads/2021/02/ECHO-2.4G-manual202001120%EF%BC%89.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/echo-2-4g-wireless-neckloop-system/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_a-200-personal-sound-amplifier_1792151551921","A-200 Personal Sound Amplifier","Operating System: Other","# A-200 Personal Sound Amplifier\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nA-200 Personal Sound Amplifier is a stereo personal sound amplifier device designed for people with hearing impairments. The device helps people with hearing difficulties to link with the outside world. It has two integrated microphones which helps the user to determine the direction of the sound source within an 8’ to 10’ radius. Furthermore, it supports customization for individual users as well as it allows users to adjust frequency response, and keeps the volume levels within a comfortable range.\n\nManufacture: Sennheiser\nhttps://en-us.sennheiser.com/tv-listening-listening-amplifier-tv-radio-music-a-200\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/a-200-personal-sound-amplifier/","MADA Portal","web","https://at.mada.org.qa/technology/a-200-personal-sound-amplifier/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/A-200-Personal-Sound-Amplifier-1.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/A-200-Personal-Sound-Amplifier-1.png\"]}",0,NULL,NULL,"2026-10-16T11:52:31.921Z","2026-10-16T11:52:31.921Z","A-200 Personal Sound Amplifier","","","Operating System: Other",NULL,NULL,"# A-200 Personal Sound Amplifier\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nA-200 Personal Sound Amplifier is a stereo personal sound amplifier device designed for people with hearing impairments. The device helps people with hearing difficulties to link with the outside world. It has two integrated microphones which helps the user to determine the direction of the sound source within an 8’ to 10’ radius. Furthermore, it supports customization for individual users as well as it allows users to adjust frequency response, and keeps the volume levels within a comfortable range.\n\nManufacture: Sennheiser\nhttps://en-us.sennheiser.com/tv-listening-listening-amplifier-tv-radio-music-a-200\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/a-200-personal-sound-amplifier/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_amigo-classroom-fm-system_1792151554300","Amigo Classroom FM System","Operating System: Other","# Amigo Classroom FM System\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nAmigo Classroom FM System is an FM amplification device designed for people with hearing impairments. The device helps children with hearing difficulties to link with the outside world whether at home or at school. The device consists of three main components: microphone, transmitter, and receiver. The microphone picks up the teacher’s voice and the transmitter sends it directly to the child’s receiver for amplification within the hearing aids. In addition, it has LED indicator confirms that the child is receiving a clear signal, and discreet receivers that stay in place.\n\nManufacture: Oticon\nhttps://www.oticon.com/solutions/for-children/amigo-fmIntroduction\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/amigo-classroom-fm-system/","MADA Portal","web","https://at.mada.org.qa/technology/amigo-classroom-fm-system/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Amigo-Classroom-FM-System.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Amigo-Classroom-FM-System.png\"]}",0,NULL,NULL,"2026-10-16T11:52:34.300Z","2026-10-16T11:52:34.300Z","Amigo Classroom FM System","","","Operating System: Other",NULL,NULL,"# Amigo Classroom FM System\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nAmigo Classroom FM System is an FM amplification device designed for people with hearing impairments. The device helps children with hearing difficulties to link with the outside world whether at home or at school. The device consists of three main components: microphone, transmitter, and receiver. The microphone picks up the teacher’s voice and the transmitter sends it directly to the child’s receiver for amplification within the hearing aids. In addition, it has LED indicator confirms that the child is receiving a clear signal, and discreet receivers that stay in place.\n\nManufacture: Oticon\nhttps://www.oticon.com/solutions/for-children/amigo-fmIntroduction\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/amigo-classroom-fm-system/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_chatpack-desktop-sound-field-system-model-ta-1_1792151556512","Chatpack Desktop Sound Field System (Model TA-1)","Operating System: Other","# Chatpack Desktop Sound Field System (Model TA-1)\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nChatpack Desktop Sound Field System, model TA-1, is an FM amplification device designed for people with hearing impairments. The device helps people with hearing difficulties to link with the outside world whether at home or at school. The device increases the teacher voice over the background noise for example. The device combines digitally synthesized receiver, transmitter, headset, ChatPack carrying pouch, and convenient system carrying case. Furthermore, the receiver can be removed which allows the user to use it as personal FM receiver with earphones, neck-loop, or direct audio input cards.\n\nManufacture: Comtek Communications Technology, Inc. (https://comtek.com)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/chatpack-desktop-sound-field-system-model-ta-1/","MADA Portal","web","https://at.mada.org.qa/technology/chatpack-desktop-sound-field-system-model-ta-1/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Chatpack-Desktop-Sound-Field-System-Model-TA-1.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Chatpack-Desktop-Sound-Field-System-Model-TA-1.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:36.512Z","2026-10-16T11:52:36.512Z","Chatpack Desktop Sound Field System (Model TA-1)","","","Operating System: Other",NULL,NULL,"# Chatpack Desktop Sound Field System (Model TA-1)\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nChatpack Desktop Sound Field System, model TA-1, is an FM amplification device designed for people with hearing impairments. The device helps people with hearing difficulties to link with the outside world whether at home or at school. The device increases the teacher voice over the background noise for example. The device combines digitally synthesized receiver, transmitter, headset, ChatPack carrying pouch, and convenient system carrying case. Furthermore, the receiver can be removed which allows the user to use it as personal FM receiver with earphones, neck-loop, or direct audio input cards.\n\nManufacture: Comtek Communications Technology, Inc. (https://comtek.com)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/chatpack-desktop-sound-field-system-model-ta-1/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_comfort-contego-with-headphone-or-neck-loop_1792151558899","Comfort Contego with Headphone or Neck Loop","Operating System: Other","# Comfort Contego with Headphone or Neck Loop\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nComfort Contego is a high definition, digital wireless FM communication system designed for people with hearing impairments. The device transmits encrypted signal over secure coded channels. It also can be used at work, school or public places as well as it can be connected directly to television, and sound system audio. Furthermore, it has a built-in zoom microphones which allows the user to adjust the sound. Moreover, when the device is used with the neck loop extension cord, the receiver can be placed on a tabletop to provide a second directional microphone and that helps users in conference room or meeting setting. Also, the device allows users to hear their own voices or voices around them while watching the TV for example.\n\nManufacture: Comfort Audio (https://teltex.com/content/userguides/Comfort-Audio-Contego-User-Guide.pdf)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/comfort-contego-with-headphone-or-neck-loop/","MADA Portal","web","https://at.mada.org.qa/technology/comfort-contego-with-headphone-or-neck-loop/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Comfort-Contego-with-Headphone-or-Neck-Loop.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/Comfort-Contego-with-Headphone-or-Neck-Loop.png\"]}",0,NULL,NULL,"2026-10-16T11:52:38.899Z","2026-10-16T11:52:38.899Z","Comfort Contego with Headphone or Neck Loop","","","Operating System: Other",NULL,NULL,"# Comfort Contego with Headphone or Neck Loop\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nComfort Contego is a high definition, digital wireless FM communication system designed for people with hearing impairments. The device transmits encrypted signal over secure coded channels. It also can be used at work, school or public places as well as it can be connected directly to television, and sound system audio. Furthermore, it has a built-in zoom microphones which allows the user to adjust the sound. Moreover, when the device is used with the neck loop extension cord, the receiver can be placed on a tabletop to provide a second directional microphone and that helps users in conference room or meeting setting. Also, the device allows users to hear their own voices or voices around them while watching the TV for example.\n\nManufacture: Comfort Audio (https://teltex.com/content/userguides/Comfort-Audio-Contego-User-Guide.pdf)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/comfort-contego-with-headphone-or-neck-loop/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_hearit-all-amplifier_1792151561096","HearIt All Amplifier","Operating System: Other","# HearIt All Amplifier\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nHearIt All Amplifier is a wireless communication system designed for people with hearing impairments which allows users to use it for TV and stereo systems, landline telephones, mobile telephones, and conversation. The device consists of a combined docking and charging unit, a handheld microphone with transmitter and a body-worn receiver with a neck loop. In addition, it allows users to talk on the phone while driving via Bluetooth connection between the device and the telephone. The product is also available with neck loop, Wrist strap and headphones.\n\nManufacture: Diatec Canada\nhttps://diateccanada.com/en/hearit-all-wireless-communication-amplifier\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/hearit-all-amplifier/","MADA Portal","web","https://at.mada.org.qa/technology/hearit-all-amplifier/",NULL,"sensory-hearing","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/HearIt-All-Amplifier-.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2020/03/HearIt-All-Amplifier-.png\"]}",0,NULL,NULL,"2026-10-16T11:52:41.096Z","2026-10-16T11:52:41.096Z","HearIt All Amplifier","","","Operating System: Other",NULL,NULL,"# HearIt All Amplifier\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nHearIt All Amplifier is a wireless communication system designed for people with hearing impairments which allows users to use it for TV and stereo systems, landline telephones, mobile telephones, and conversation. The device consists of a combined docking and charging unit, a handheld microphone with transmitter and a body-worn receiver with a neck loop. In addition, it allows users to talk on the phone while driving via Bluetooth connection between the device and the telephone. The product is also available with neck loop, Wrist strap and headphones.\n\nManufacture: Diatec Canada\nhttps://diateccanada.com/en/hearit-all-wireless-communication-amplifier\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-hearing\n\n## Nguồn\nhttps://at.mada.org.qa/technology/hearit-all-amplifier/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_victor-reader-stratus4-m-daisy-and-mp3-player_1792151564807","Victor Reader Stratus4 M – Daisy and MP3 player","Operating System: Other","# Victor Reader Stratus4 M – Daisy and MP3 player\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nVictor Reader Stratus M multimedia player gives you exceptional access to DAISY books, recorded books, music, and computer documents from more media sources than ever. The Stratus4 M model has a 4-arrow keypad developed for ideal reading navigation. User-friendly and accessible: Victor Reader Stratus M is an audio player for everyone.\n\nManufacturer: Humanware Humanware – Victor Reader Stratus4 M – Daisy and MP3 player – Low vision and blindness solutions: Magnifiers, Braille devices, Audio assistants, Orientation and mobility, and Embossers\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/victor-reader-stratus4-m-daisy-and-mp3-player/","MADA Portal","web","https://at.mada.org.qa/technology/victor-reader-stratus4-m-daisy-and-mp3-player/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-104431.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-104431.png\"]}",0,NULL,NULL,"2026-10-16T11:52:44.807Z","2026-10-16T11:52:44.807Z","Victor Reader Stratus4 M – Daisy and MP3 player","","","Operating System: Other",NULL,NULL,"# Victor Reader Stratus4 M – Daisy and MP3 player\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nVictor Reader Stratus M multimedia player gives you exceptional access to DAISY books, recorded books, music, and computer documents from more media sources than ever. The Stratus4 M model has a 4-arrow keypad developed for ideal reading navigation. User-friendly and accessible: Victor Reader Stratus M is an audio player for everyone.\n\nManufacturer: Humanware Humanware – Victor Reader Stratus4 M – Daisy and MP3 player – Low vision and blindness solutions: Magnifiers, Braille devices, Audio assistants, Orientation and mobility, and Embossers\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/victor-reader-stratus4-m-daisy-and-mp3-player/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_explore-12_1792151566731","Explore 12","Operating System: Other","# Explore 12\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nExplore 12 – Portable video magnifier, the ultimate electronic portable magnifier designed specifically for individuals living with low vision or sight loss. This cutting-edge video magnifier offers unmatched HD image quality, taking your reading and viewing experience to extraordinary heights. Whether you’re exploring text or examining objects up close or from a distance, prepare to be astounded by its capabilities.\n\nManufacturer: Humanware Humanware – Humanware – explorē 12 – Portable video magnifier – Low vision and blindness solutions: Magnifiers, Braille devices, Audio assistants, Orientation and mobility, and Embossers – Low vision and blindness solutions: Magnifiers, Braille devices, Audio assistants, Orientation and mobility, and Embossers\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/explore-12/","MADA Portal","web","https://at.mada.org.qa/technology/explore-12/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-103513.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-103513.png\"]}",0,NULL,NULL,"2026-10-16T11:52:46.731Z","2026-10-16T11:52:46.731Z","Explore 12","","","Operating System: Other",NULL,NULL,"# Explore 12\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nExplore 12 – Portable video magnifier, the ultimate electronic portable magnifier designed specifically for individuals living with low vision or sight loss. This cutting-edge video magnifier offers unmatched HD image quality, taking your reading and viewing experience to extraordinary heights. Whether you’re exploring text or examining objects up close or from a distance, prepare to be astounded by its capabilities.\n\nManufacturer: Humanware Humanware – Humanware – explorē 12 – Portable video magnifier – Low vision and blindness solutions: Magnifiers, Braille devices, Audio assistants, Orientation and mobility, and Embossers – Low vision and blindness solutions: Magnifiers, Braille devices, Audio assistants, Orientation and mobility, and Embossers\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/explore-12/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_helix-hd_1792151568539","Helix HD","Operating System: Other","# Helix HD\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nHelix HD is an affordable, portable & lightweight HD video magnifier with an easy to use wireless control pad. Its unique dual-camera system offers a complete solution for users requiring full page width magnification of any text or images up to 150x (24″ monitor).\n\nIts compact and portable design makes it easy to move between multiple rooms, and between home and work.\n\nManufacturer: VisionAid International (http://www.visionaid.com/)\n\nSupport Manuals: http://www.visionaid.com/phpincludes/en/support/helix_hd/helix_hd.php\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/helix-hd/","MADA Portal","web","https://at.mada.org.qa/technology/helix-hd/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Helix-HD.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Helix-HD.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:48.539Z","2026-10-16T11:52:48.539Z","Helix HD","","","Operating System: Other",NULL,NULL,"# Helix HD\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nHelix HD is an affordable, portable & lightweight HD video magnifier with an easy to use wireless control pad. Its unique dual-camera system offers a complete solution for users requiring full page width magnification of any text or images up to 150x (24″ monitor).\n\nIts compact and portable design makes it easy to move between multiple rooms, and between home and work.\n\nManufacturer: VisionAid International (http://www.visionaid.com/)\n\nSupport Manuals: http://www.visionaid.com/phpincludes/en/support/helix_hd/helix_hd.php\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/helix-hd/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_braillesense-6_1792151570518","BrailleSense 6","Operating System: Android","# BrailleSense 6\n\n## Mô tả\nOperating System: Android\n\n## Chi tiết sản phẩm\nBrailleSense 6 is an innovative collaboration of Braille and mainstream technology, offering the blind and visually impaired unprecedented accessible and intuitive productivity in today’s tablet-based world.\n\nWith its built-in apps for document creation, e-mail, Web browsing, media and DAISY playback, contacts, calendar and database management, and book search and download, BrailleSense 6 is a powerful productivity tool that promotes Braille literacy through its Braille-centric command structure; while supporting Google Apps such as Google Drive, Google Docs, Google Sheets, Google Slides and Google Classroom; ensuring students and professionals can be intuitively productive and efficiently collaborative in the contemporary world.\n\nManufacturer: SELVAS BLV (product page, support page)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/braillesense-6/","MADA Portal","web","https://at.mada.org.qa/technology/braillesense-6/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/BrailleSesnse-6.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/BrailleSesnse-6.png\"]}",0,NULL,NULL,"2026-10-16T11:52:50.518Z","2026-10-16T11:52:50.518Z","BrailleSense 6","","","Operating System: Android",NULL,NULL,"# BrailleSense 6\n\n## Mô tả\nOperating System: Android\n\n## Chi tiết sản phẩm\nBrailleSense 6 is an innovative collaboration of Braille and mainstream technology, offering the blind and visually impaired unprecedented accessible and intuitive productivity in today’s tablet-based world.\n\nWith its built-in apps for document creation, e-mail, Web browsing, media and DAISY playback, contacts, calendar and database management, and book search and download, BrailleSense 6 is a powerful productivity tool that promotes Braille literacy through its Braille-centric command structure; while supporting Google Apps such as Google Drive, Google Docs, Google Sheets, Google Slides and Google Classroom; ensuring students and professionals can be intuitively productive and efficiently collaborative in the contemporary world.\n\nManufacturer: SELVAS BLV (product page, support page)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/braillesense-6/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_nvda-with-arabic-voices_1792151572568","NVDA with Arabic voices","Operating System: Windows","# NVDA with Arabic voices\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nNonVisual Desktop Access (NVDA) is a free and open source screen reader for the Microsoft Windows operating system. Providing feedback via synthetic speech and Braille, it enables blind or vision impaired people to access computers running Windows for no more cost than a sighted person.\n\nManufacturer: NV Access (https://www.nvaccess.org/)\n\nNVDA Free Download: https://www.nvaccess.org/download/\n\nSupporting Manuals: https://www.nvaccess.org/files/nvda/documentation/userGuide.html\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/nvda-with-arabic-voices/","MADA Portal","web","https://at.mada.org.qa/technology/nvda-with-arabic-voices/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/NVDA.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/NVDA.png\"]}",0,NULL,NULL,"2026-10-16T11:52:52.568Z","2026-10-16T11:52:52.568Z","NVDA with Arabic voices","","","Operating System: Windows",NULL,NULL,"# NVDA with Arabic voices\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nNonVisual Desktop Access (NVDA) is a free and open source screen reader for the Microsoft Windows operating system. Providing feedback via synthetic speech and Braille, it enables blind or vision impaired people to access computers running Windows for no more cost than a sighted person.\n\nManufacturer: NV Access (https://www.nvaccess.org/)\n\nNVDA Free Download: https://www.nvaccess.org/download/\n\nSupporting Manuals: https://www.nvaccess.org/files/nvda/documentation/userGuide.html\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/nvda-with-arabic-voices/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_duxbury-braille-translation-sw_1792151574698","Duxbury Braille Translation SW","Duxbury Braille Translation (DBT) is created to make braille production easier and braille accessible to more people.  DBT supports braille translation for over 200 languages. DBT can produce contracted and uncontracted braille, mathematics braille, and technical braille.","# Duxbury Braille Translation SW\n\n## Mô tả\nDuxbury Braille Translation (DBT) is created to make braille production easier and braille accessible to more people.  DBT supports braille translation for over 200 languages. DBT can produce contracted and uncontracted braille, mathematics braille, and technical braille.\n\n## Chi tiết sản phẩm\nDuxbury Braille Translation (DBT) is created to make braille production easier and braille accessible to more people.  DBT supports braille translation for over 200 languages. DBT can produce contracted and uncontracted braille, mathematics braille, and technical braille.\n\nManufacturer: Duxbury Systems (https://www.duxburysystems.com/default.asp)\n\nSupporting Documents: https://www.duxburysystems.com/braille_main.asp\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/duxbury-braille-translation-sw/","MADA Portal","web","https://at.mada.org.qa/technology/duxbury-braille-translation-sw/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/DBT.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/DBT.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:54.698Z","2026-10-16T11:52:54.698Z","Duxbury Braille Translation SW","","","Duxbury Braille Translation (DBT) is created to make braille production easier and braille accessible to more people.  DBT supports braille translation for over 200 languages. DBT can produce contracted and uncontracted braille, mathematics braille, and technical braille.",NULL,NULL,"# Duxbury Braille Translation SW\n\n## Mô tả\nDuxbury Braille Translation (DBT) is created to make braille production easier and braille accessible to more people.  DBT supports braille translation for over 200 languages. DBT can produce contracted and uncontracted braille, mathematics braille, and technical braille.\n\n## Chi tiết sản phẩm\nDuxbury Braille Translation (DBT) is created to make braille production easier and braille accessible to more people.  DBT supports braille translation for over 200 languages. DBT can produce contracted and uncontracted braille, mathematics braille, and technical braille.\n\nManufacturer: Duxbury Systems (https://www.duxburysystems.com/default.asp)\n\nSupporting Documents: https://www.duxburysystems.com/braille_main.asp\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/duxbury-braille-translation-sw/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_eurobraille-b-note-20_1792151576968","Eurobraille b.note 20","Operating System: Other","# Eurobraille b.note 20\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe 20-character version of the b.note Braille notetaker combines the functions of a Braille display with built-in word processing and notetaking functions in a highly portable package. Connect it to a computer via USB or Bluetooth to use it as a Braille keyboard or edit your text files directly on the device itself on the go.\n\nManufacturer: EuroBraille (https://www.eurobraille.com/produit/b-note-20-b-note-40/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/eurobraille-b-note-20/","MADA Portal","web","https://at.mada.org.qa/technology/eurobraille-b-note-20/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/bnote-standard-02.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/bnote-standard-02.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:56.968Z","2026-10-16T11:52:56.968Z","Eurobraille b.note 20","","","Operating System: Other",NULL,NULL,"# Eurobraille b.note 20\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe 20-character version of the b.note Braille notetaker combines the functions of a Braille display with built-in word processing and notetaking functions in a highly portable package. Connect it to a computer via USB or Bluetooth to use it as a Braille keyboard or edit your text files directly on the device itself on the go.\n\nManufacturer: EuroBraille (https://www.eurobraille.com/produit/b-note-20-b-note-40/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/eurobraille-b-note-20/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_visionbuddy_1792151579222","VisionBuddy","Operating System: Other","# VisionBuddy\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nVision Buddy is an assistive device designed for the visually impaired to perform day to day tasks.\n\n– Use the TV Hub to connect to your cable box, streamer or any other provider to see your favorite TV programs with enhanced image quality.\n\n– Look at your desktop within the headset with the ability to zoom using Computer Link or read with the CCTV Mini.\n\n– With a click of a button switch to magnification/camera mode and see the world around you. It’s that simpl\n\nManufacturer: Vision Buddy (https://getvisionbuddy.com/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/visionbuddy/","MADA Portal","web","https://at.mada.org.qa/technology/visionbuddy/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/Vision-Buddy-Headset.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/Vision-Buddy-Headset.jpg\"]}",0,NULL,NULL,"2026-10-16T11:52:59.222Z","2026-10-16T11:52:59.222Z","VisionBuddy","","","Operating System: Other",NULL,NULL,"# VisionBuddy\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nVision Buddy is an assistive device designed for the visually impaired to perform day to day tasks.\n\n– Use the TV Hub to connect to your cable box, streamer or any other provider to see your favorite TV programs with enhanced image quality.\n\n– Look at your desktop within the headset with the ability to zoom using Computer Link or read with the CCTV Mini.\n\n– With a click of a button switch to magnification/camera mode and see the world around you. It’s that simpl\n\nManufacturer: Vision Buddy (https://getvisionbuddy.com/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/visionbuddy/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_cloverbook-pro_1792151581574","CloverBook Pro","Operating System: Other","# CloverBook Pro\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nCloverBook Pro is a foldable video magnifier with touchscreen navigation, distance camera and OCR features.\nCloverBook Pro offers a large, 12.5-inch FHD screen with full-page text-to-speech scanning; all in a light, foldable, extremely portable unit, complete with an attractive protective carry case. CloverBook Pro is powerful but simple to use; with traditional (tactile) controls, like magnification and contrast knobs. It also has a touchscreen for people who prefer to use that.\n\nManufacturer: SightCare (http://www.sightcare.com.cn/products)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/cloverbook-pro/","MADA Portal","web","https://at.mada.org.qa/technology/cloverbook-pro/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/CloverBookPro_Photo.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/CloverBookPro_Photo.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:01.574Z","2026-10-16T11:53:01.574Z","CloverBook Pro","","","Operating System: Other",NULL,NULL,"# CloverBook Pro\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nCloverBook Pro is a foldable video magnifier with touchscreen navigation, distance camera and OCR features.\nCloverBook Pro offers a large, 12.5-inch FHD screen with full-page text-to-speech scanning; all in a light, foldable, extremely portable unit, complete with an attractive protective carry case. CloverBook Pro is powerful but simple to use; with traditional (tactile) controls, like magnification and contrast knobs. It also has a touchscreen for people who prefer to use that.\n\nManufacturer: SightCare (http://www.sightcare.com.cn/products)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/cloverbook-pro/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_rs-games_1792151583728","RS Games","Operating System: Windows, iOS","# RS Games\n\n## Mô tả\nOperating System: Windows, iOS\n\n## Chi tiết sản phẩm\nRS Games is a collection of 19 accessible tabletop games for the blind and visually impaired, currently available for iOS devices. Games can be played alone, with others over the Internet, or with computer-controlled players.\n\nDownload the app\nhttps://apps.apple.com/us/app/rs-games/id1118710108\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/rs-games/","MADA Portal","web","https://at.mada.org.qa/technology/rs-games/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/04/RMGames.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/04/RMGames.png\"]}",0,NULL,NULL,"2026-10-16T11:53:03.728Z","2026-10-16T11:53:03.728Z","RS Games","","","Operating System: Windows, iOS",NULL,NULL,"# RS Games\n\n## Mô tả\nOperating System: Windows, iOS\n\n## Chi tiết sản phẩm\nRS Games is a collection of 19 accessible tabletop games for the blind and visually impaired, currently available for iOS devices. Games can be played alone, with others over the Internet, or with computer-controlled players.\n\nDownload the app\nhttps://apps.apple.com/us/app/rs-games/id1118710108\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/rs-games/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_thinkerbell-annie_1792151585823","Thinkerbell Annie","Operating System: Other","# Thinkerbell Annie\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThinkerbell Annie is a Self-Learning Braille Literacy Device for a visually impaired student to learn to read and type in Braille on their own, while having fun.\n\nAnnie manual: https://www.thinkerbelllabs.com/annie/manual\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/thinkerbell-annie/","MADA Portal","web","https://at.mada.org.qa/technology/thinkerbell-annie/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Thinkerbell-Annie.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Thinkerbell-Annie.png\"]}",0,NULL,NULL,"2026-10-16T11:53:05.823Z","2026-10-16T11:53:05.823Z","Thinkerbell Annie","","","Operating System: Other",NULL,NULL,"# Thinkerbell Annie\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThinkerbell Annie is a Self-Learning Braille Literacy Device for a visually impaired student to learn to read and type in Braille on their own, while having fun.\n\nAnnie manual: https://www.thinkerbelllabs.com/annie/manual\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/thinkerbell-annie/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_qatari-money-reader-app_1792151588192","Qatari Money Reader App","Operating System: iOS","# Qatari Money Reader App\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nQatari Money Reader App is developed to detect and read Qatari Riyal currency notes using the camera of the smartphone. Primarily, identifying the value of banknotes is one of the main challenges faced by people with visual impairments.\n\nIt also calculate multiple currencies, exchange rates and can identify fake notes.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/qatari-money-reader-app/","MADA Portal","web","https://at.mada.org.qa/technology/qatari-money-reader-app/",NULL,"sensory-vision","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Qatar-Money-Reader.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Qatar-Money-Reader.png\"]}",0,NULL,NULL,"2026-10-16T11:53:08.192Z","2026-10-16T11:53:08.192Z","Qatari Money Reader App","","","Operating System: iOS",NULL,NULL,"# Qatari Money Reader App\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nQatari Money Reader App is developed to detect and read Qatari Riyal currency notes using the camera of the smartphone. Primarily, identifying the value of banknotes is one of the main challenges faced by people with visual impairments.\n\nIt also calculate multiple currencies, exchange rates and can identify fake notes.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** sensory-vision\n\n## Nguồn\nhttps://at.mada.org.qa/technology/qatari-money-reader-app/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_attainment-talker-24_1792151592054","Attainment Talker 24","Operating System: Other","# Attainment Talker 24\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Attainment Talker 24 has 24 messages with ¾-inch active touch areas.\n\nA clear, plastic pocket holds and protects communication cues. Hold the talker with 2 hands and activate speech with your thumb, or use it as a tabletop talker. A neoprene glove keeps the talker from sliding. Powered by 2 AAA batteries.\n\nInstruction Manual: https://www.attainmentcompany.com/mwdownloads/download/link/id/1163\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/attainment-talker-24/","MADA Portal","web","https://at.mada.org.qa/technology/attainment-talker-24/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Attainment-Talker-24.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Attainment-Talker-24.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:12.054Z","2026-10-16T11:53:12.054Z","Attainment Talker 24","","","Operating System: Other",NULL,NULL,"# Attainment Talker 24\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Attainment Talker 24 has 24 messages with ¾-inch active touch areas.\n\nA clear, plastic pocket holds and protects communication cues. Hold the talker with 2 hands and activate speech with your thumb, or use it as a tabletop talker. A neoprene glove keeps the talker from sliding. Powered by 2 AAA batteries.\n\nInstruction Manual: https://www.attainmentcompany.com/mwdownloads/download/link/id/1163\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/attainment-talker-24/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_gotalk-select_1792151594092","GoTalk Select","Operating System: Other","# GoTalk Select\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nGoTalk Select is a wearable, augmentative and alternative communication (AAC) device with you using the clip or lanyard (both included) or just take it along in your pocket. Small, light, and rechargeable via USB, the GoTalk Select offers four programmable message buttons on each of three levels for a total of 12 wearable quick messages.\n\nProgram with 1, 2, 3, or 4 messages at a time, with each message button measuring at 2.75 cm x 2.75 cm. Powerful, high-quality speaker allows for remarkable volume from a small device.\n\nManufacturer: Attainment Company (https://www.attainmentcompany.com/)\n\nGoTalk Go Support: https://www.attainmentcompany.com/mwdownloads/download/link/id/1503\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/gotalk-select/","MADA Portal","web","https://at.mada.org.qa/technology/gotalk-select/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/GoTalk-Select.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/GoTalk-Select.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:14.092Z","2026-10-16T11:53:14.092Z","GoTalk Select","","","Operating System: Other",NULL,NULL,"# GoTalk Select\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nGoTalk Select is a wearable, augmentative and alternative communication (AAC) device with you using the clip or lanyard (both included) or just take it along in your pocket. Small, light, and rechargeable via USB, the GoTalk Select offers four programmable message buttons on each of three levels for a total of 12 wearable quick messages.\n\nProgram with 1, 2, 3, or 4 messages at a time, with each message button measuring at 2.75 cm x 2.75 cm. Powerful, high-quality speaker allows for remarkable volume from a small device.\n\nManufacturer: Attainment Company (https://www.attainmentcompany.com/)\n\nGoTalk Go Support: https://www.attainmentcompany.com/mwdownloads/download/link/id/1503\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/gotalk-select/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_gotalk-go_1792151596115","GoTalk Go","Operating System: Other","# GoTalk Go\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe rechargeable GoTalk Go offers three programmable message buttons. Try the new easier-to-use capacitive touch buttons to activate a message. Program 1, 2, or 3 messages on each of three levels for a total capacity of nine messages!\n\nIt looks similar to a watch with the plastic wristband, providing a convenient, wearable AAC device for on-the-go! The robust volume of this device will amaze you. Great to use for conversations in the cafeteria, at recess, on community outings, and many more places.\n\nManufacturer: Attainment Company (https://www.attainmentcompany.com/)\n\nGoTalk Go Support: https://www.attainmentcompany.com/mwdownloads/download/link/id/1503\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/gotalk-go/","MADA Portal","web","https://at.mada.org.qa/technology/gotalk-go/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/GoTalk-Go.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/GoTalk-Go.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:16.116Z","2026-10-16T11:53:16.116Z","GoTalk Go","","","Operating System: Other",NULL,NULL,"# GoTalk Go\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe rechargeable GoTalk Go offers three programmable message buttons. Try the new easier-to-use capacitive touch buttons to activate a message. Program 1, 2, or 3 messages on each of three levels for a total capacity of nine messages!\n\nIt looks similar to a watch with the plastic wristband, providing a convenient, wearable AAC device for on-the-go! The robust volume of this device will amaze you. Great to use for conversations in the cafeteria, at recess, on community outings, and many more places.\n\nManufacturer: Attainment Company (https://www.attainmentcompany.com/)\n\nGoTalk Go Support: https://www.attainmentcompany.com/mwdownloads/download/link/id/1503\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/gotalk-go/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_td-pilot_1792151597912","TD Pilot","Operating System: iOS","# TD Pilot\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nTD Pilot is an eye-controlled communication device for iPad. Designed to empower people with conditions such as ALS/MND, spinal cord injury or cerebral palsy to communicate and use their favourite apps, this iPad OS-based speech generating device features the world’s leading eye tracker.\n\nManufacturer: Tobii Dynavox (https://www.tobiidynavox.com/pages/tdpilot)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/td-pilot/","MADA Portal","web","https://at.mada.org.qa/technology/td-pilot/",NULL,"neuromusculoskeletal-movement","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/TD-pilot.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/TD-pilot.png\"]}",0,NULL,NULL,"2026-10-16T11:53:17.912Z","2026-10-16T11:54:21.037Z","TD Pilot","","","Operating System: iOS",NULL,NULL,"# TD Pilot\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nTD Pilot is an eye-controlled communication device for iPad. Designed to empower people with conditions such as ALS/MND, spinal cord injury or cerebral palsy to communicate and use their favourite apps, this iPad OS-based speech generating device features the world’s leading eye tracker.\n\nManufacturer: Tobii Dynavox (https://www.tobiidynavox.com/pages/tdpilot)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/td-pilot/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_tawasol-aac-app_1792151599973","Tawasol AAC app","Operating System: iOS","# Tawasol AAC app\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nTawasol AAC App gives people with communication difficulties and children with Autism Spectrum Disorder (ASD) the ability to express themselves and build sentences in Arabic through a wide range of symbols. The app allows users to add symbols and vocabulary as they need, making it ideal for a wide range of people with disabilities, including adults such as trauma victims and those who temporarily need a communication tool. This application supports the use of alternative buttons and other access tools for mobile devices, making it easy to use for people with severe physical disabilities to communicate with their family members.\n\nDownload Tawasol AAC app: https://mip.mada.org.qa/solution/tawasol-aac-app/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tawasol-aac-app/","MADA Portal","web","https://at.mada.org.qa/technology/tawasol-aac-app/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/tawasol.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/tawasol.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:19.973Z","2026-10-16T11:53:19.973Z","Tawasol AAC app","","","Operating System: iOS",NULL,NULL,"# Tawasol AAC app\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nTawasol AAC App gives people with communication difficulties and children with Autism Spectrum Disorder (ASD) the ability to express themselves and build sentences in Arabic through a wide range of symbols. The app allows users to add symbols and vocabulary as they need, making it ideal for a wide range of people with disabilities, including adults such as trauma victims and those who temporarily need a communication tool. This application supports the use of alternative buttons and other access tools for mobile devices, making it easy to use for people with severe physical disabilities to communicate with their family members.\n\nDownload Tawasol AAC app: https://mip.mada.org.qa/solution/tawasol-aac-app/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tawasol-aac-app/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_tawasol-symbols_1792151601956","Tawasol Symbols","Operating System: Windows, iOS","# Tawasol Symbols\n\n## Mô tả\nOperating System: Windows, iOS\n\n## Chi tiết sản phẩm\nTAWASOL Symbols dictionary is a bilingual Arabic / English symbol dictionary of frequently used words in spoken and written communication (Tawasol in Arabic) to support Alternative and Augmentative Communication (AAC) users, individuals who may have low levels of literacy, learning disabilities or specific learning difficulties and individuals who have social interaction difficulties.\n\nDownload Tawasol symbols: https://tawasol.mada.org.qa/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tawasol-symbols/","MADA Portal","web","https://at.mada.org.qa/technology/tawasol-symbols/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Tawasol-symbols.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Tawasol-symbols.png\"]}",0,NULL,NULL,"2026-10-16T11:53:21.956Z","2026-10-16T11:53:45.712Z","Tawasol Symbols","","","Operating System: Windows, iOS",NULL,NULL,"# Tawasol Symbols\n\n## Mô tả\nOperating System: Windows, iOS\n\n## Chi tiết sản phẩm\nTAWASOL Symbols dictionary is a bilingual Arabic / English symbol dictionary of frequently used words in spoken and written communication (Tawasol in Arabic) to support Alternative and Augmentative Communication (AAC) users, individuals who may have low levels of literacy, learning disabilities or specific learning difficulties and individuals who have social interaction difficulties.\n\nDownload Tawasol symbols: https://tawasol.mada.org.qa/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tawasol-symbols/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_grid-pad-10s_1792151604133","Grid Pad 10s","Operating System: Other","# Grid Pad 10s\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nGrid Pad 10s is a dedicated, multi-access device designed for users who want a portable and rugged communication aid. The high-quality engineering and unique set of features bring you a next generation AAC device designed with independence and durability in mind.\n\nThe second screen adds a whole new way to communicate by showing your message on the front of your device. This can be helpful in noisy environments in addition to using your Grid voice, helping you get your message across clearly to the person you’re communicating with.\n\nGrid Pad 10s is a multi-access device, so there are lots of ways to interact with it. There is a touch screen which you can use with a keyguard, two switch ports for use with switches, two USB ports for use with USB access devices like joysticks, and\na headphone and mic combo port. You can also connect Bluetooth devices to your Grid Pad such as wireless switches, pointers, headphones and more.\n\nGEWA infrared Environment Control allows you to operate devices around your home, like your TV and other remote controlled gadgets. The front facing IR learning window provides ease of programming, and the multi-directional infrared LEDs give you a powerful 10m range signal.\n\nGrid Pad 10s User Guide: https://thinksmartbox.com/product/grid-pad-10s/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/grid-pad-10s/","MADA Portal","web","https://at.mada.org.qa/technology/grid-pad-10s/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Grid-Pad-10s.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Grid-Pad-10s.png\"]}",0,NULL,NULL,"2026-10-16T11:53:24.133Z","2026-10-16T11:53:24.133Z","Grid Pad 10s","","","Operating System: Other",NULL,NULL,"# Grid Pad 10s\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nGrid Pad 10s is a dedicated, multi-access device designed for users who want a portable and rugged communication aid. The high-quality engineering and unique set of features bring you a next generation AAC device designed with independence and durability in mind.\n\nThe second screen adds a whole new way to communicate by showing your message on the front of your device. This can be helpful in noisy environments in addition to using your Grid voice, helping you get your message across clearly to the person you’re communicating with.\n\nGrid Pad 10s is a multi-access device, so there are lots of ways to interact with it. There is a touch screen which you can use with a keyguard, two switch ports for use with switches, two USB ports for use with USB access devices like joysticks, and\na headphone and mic combo port. You can also connect Bluetooth devices to your Grid Pad such as wireless switches, pointers, headphones and more.\n\nGEWA infrared Environment Control allows you to operate devices around your home, like your TV and other remote controlled gadgets. The front facing IR learning window provides ease of programming, and the multi-directional infrared LEDs give you a powerful 10m range signal.\n\nGrid Pad 10s User Guide: https://thinksmartbox.com/product/grid-pad-10s/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/grid-pad-10s/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_gotalk-now_1792151606058","GoTalk Now","Operating System: iOS","# GoTalk Now\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nGoTalk Now provides all the tools you’ll need in an AAC app, plus so much more! Newly included with NOW are the Core word communication pages. Core vocabulary refer to a small collection of words that make up the majority of words used in daily communication. Now you have instant access to a set of pages, field-tested and created by SLP Gisele Morin-Connolly, based on Project CORE research from UNC Center for Literacy and Disability Studies. These Core pages will be a great starting point and will have you communicating in no time. Communicate using one word to 36 words enhanced with these core pages and more! Create and add new pages that suit your personality too. Choose from four mix-and-match page styles: Standard, Express, Visual Scene, and Keyboard.\n\nGoTalk Now user guide: https://www.attainmentcompany.com/gotalk-now\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/gotalk-now/","MADA Portal","web","https://at.mada.org.qa/technology/gotalk-now/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/GoTalk-Nowjpg.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/GoTalk-Nowjpg.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:26.058Z","2026-10-16T11:53:26.058Z","GoTalk Now","","","Operating System: iOS",NULL,NULL,"# GoTalk Now\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nGoTalk Now provides all the tools you’ll need in an AAC app, plus so much more! Newly included with NOW are the Core word communication pages. Core vocabulary refer to a small collection of words that make up the majority of words used in daily communication. Now you have instant access to a set of pages, field-tested and created by SLP Gisele Morin-Connolly, based on Project CORE research from UNC Center for Literacy and Disability Studies. These Core pages will be a great starting point and will have you communicating in no time. Communicate using one word to 36 words enhanced with these core pages and more! Create and add new pages that suit your personality too. Choose from four mix-and-match page styles: Standard, Express, Visual Scene, and Keyboard.\n\nGoTalk Now user guide: https://www.attainmentcompany.com/gotalk-now\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/gotalk-now/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_proloquo2go_1792151608199","Proloquo2Go","Operating System: iOS","# Proloquo2Go\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nProloquo2Go is a symbol-based app helps users learn how to express themselves. Proloquo2Go puts the user’s development first, with innovative features based on clinical knowledge and user research.\n\nIt’s also one of the few AAC apps designed to support all users, from beginning to advanced. Completely customizable and designed for a range of fine-motor and visual skills, the app’s versatility makes it useful for non-verbal people with autism, Down syndrome, cerebral palsy, and a range of other diagnoses or speech impediments like apraxia and dysarthria.\n\nManufacturer: Assistiveware (https://www.assistiveware.com)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/proloquo2go/","MADA Portal","web","https://at.mada.org.qa/technology/proloquo2go/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo2Go.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo2Go.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:28.200Z","2026-10-16T11:53:28.200Z","Proloquo2Go","","","Operating System: iOS",NULL,NULL,"# Proloquo2Go\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nProloquo2Go is a symbol-based app helps users learn how to express themselves. Proloquo2Go puts the user’s development first, with innovative features based on clinical knowledge and user research.\n\nIt’s also one of the few AAC apps designed to support all users, from beginning to advanced. Completely customizable and designed for a range of fine-motor and visual skills, the app’s versatility makes it useful for non-verbal people with autism, Down syndrome, cerebral palsy, and a range of other diagnoses or speech impediments like apraxia and dysarthria.\n\nManufacturer: Assistiveware (https://www.assistiveware.com)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/proloquo2go/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_proloquo4text_1792151610329","Proloquo4Text","Operating System: iOS","# Proloquo4Text\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nThis Text to Speech app is for literate AAC users looking for an efficient text based communication app.\n\nType less and react quickly to the conversation at hand with smart features and a handy layout.\n\nPrediction learns from how you write to give you suggestions for the next thing to say.\nCreate your own phrases, group them for fast access, and easily find things you’ve said before with history.\nAccess the keyboard, words and phrases from a single screen\n\nProloquo4Text lets you be you. Choose from more than 130 voices in 18 languages including English, Arabic, Catalan, Czech Danish, Dutch, Finnish, French, German, Greek, Italian, Norwegian, Polish, Portuguese, Russian, Spanish, Swedish, and Turkish.\n\nThese voices range from friendly adult voices to genuine children’s voices. The voices are created using real recorded speech, making them feel surprisingly natural. For some languages, you even have multiple options.\n\nManufacturer: Assistiveware (https://www.assistiveware.com/products/proloquo4text)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/proloquo4text/","MADA Portal","web","https://at.mada.org.qa/technology/proloquo4text/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo4text.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Proloquo4text.png\"]}",0,NULL,NULL,"2026-10-16T11:53:30.329Z","2026-10-16T11:53:30.329Z","Proloquo4Text","","","Operating System: iOS",NULL,NULL,"# Proloquo4Text\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nThis Text to Speech app is for literate AAC users looking for an efficient text based communication app.\n\nType less and react quickly to the conversation at hand with smart features and a handy layout.\n\nPrediction learns from how you write to give you suggestions for the next thing to say.\nCreate your own phrases, group them for fast access, and easily find things you’ve said before with history.\nAccess the keyboard, words and phrases from a single screen\n\nProloquo4Text lets you be you. Choose from more than 130 voices in 18 languages including English, Arabic, Catalan, Czech Danish, Dutch, Finnish, French, German, Greek, Italian, Norwegian, Polish, Portuguese, Russian, Spanish, Swedish, and Turkish.\n\nThese voices range from friendly adult voices to genuine children’s voices. The voices are created using real recorded speech, making them feel surprisingly natural. For some languages, you even have multiple options.\n\nManufacturer: Assistiveware (https://www.assistiveware.com/products/proloquo4text)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/proloquo4text/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_coughdrop-aac_1792151612762","CoughDrop AAC","Operating System: Windows, iOS, Android, Chrome","# CoughDrop AAC\n\n## Mô tả\nOperating System: Windows, iOS, Android, Chrome\n\n## Chi tiết sản phẩm\nCoughDrop is an open, flexible augmentative and alternative communication (AAC) app for people with complex communication needs, that can grow and expand with the user, make it easier to provide meaningful supports, and provide useful insights, all in a clean, cross-platform package.\n\nCoughDrop is built to run on all major devices, including desktop computers and laptops, iPads and iPhones, Android tablets and phones, Kindles, Chromebooks, and Windows devices. The interface stays consistent across devices so that users can swap out devices with minimal interruption or confusion. CoughDrop is built on modern web standards and offers an open API and integration points to try to work with as many existing systems as possible.\n\nCoughDrop has vocabulary sets for many different levels, with built-in supports and vocabulary progression tools to start basic and grow over time. It has support for eye tracking and switches, and also new input methods like joysticks and gesture control, to give the user more flexibility.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/coughdrop-aac/","MADA Portal","web","https://at.mada.org.qa/technology/coughdrop-aac/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/CoughDrop.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/CoughDrop.png\"]}",0,NULL,NULL,"2026-10-16T11:53:32.762Z","2026-10-16T11:53:32.762Z","CoughDrop AAC","","","Operating System: Windows, iOS, Android, Chrome",NULL,NULL,"# CoughDrop AAC\n\n## Mô tả\nOperating System: Windows, iOS, Android, Chrome\n\n## Chi tiết sản phẩm\nCoughDrop is an open, flexible augmentative and alternative communication (AAC) app for people with complex communication needs, that can grow and expand with the user, make it easier to provide meaningful supports, and provide useful insights, all in a clean, cross-platform package.\n\nCoughDrop is built to run on all major devices, including desktop computers and laptops, iPads and iPhones, Android tablets and phones, Kindles, Chromebooks, and Windows devices. The interface stays consistent across devices so that users can swap out devices with minimal interruption or confusion. CoughDrop is built on modern web standards and offers an open API and integration points to try to work with as many existing systems as possible.\n\nCoughDrop has vocabulary sets for many different levels, with built-in supports and vocabulary progression tools to start basic and grow over time. It has support for eye tracking and switches, and also new input methods like joysticks and gesture control, to give the user more flexibility.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/coughdrop-aac/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_tobii-dynavox-i-series_1792151615021","Tobii Dynavox I-Series","Operating System: Windows","# Tobii Dynavox I-Series\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nThe I-Series is an eye gaze-enabled speech generating device featuring the world’s leading eye tracker. Purpose-built for people with conditions such as cerebral palsy, Rett syndrome or ALS, this Windows-based device is controlled completely with your eyes to communicate and live more independently.\n\nThe I-16 is a custom-built AAC devices that enable communication and independence for people with disabilities via eye control and other access methods.\n\nIt is the lightest, fastest and most durable integrated eye tracking device available and is packed with ground breaking innovations such as a partner window and industry-leading eye tracking performance using Tobii’s latest eye tracking sensor IS5. The partner window is a second screen, located on the back of the device, which mirrors the phrases being typed and enables true face-to-face communication\n\nMore information at https://www.tobiidynavox.com/products/i-series/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tobii-dynavox-i-series/","MADA Portal","web","https://at.mada.org.qa/technology/tobii-dynavox-i-series/",NULL,"voice-and-speech","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Tobii-Dynavox-I-16.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Tobii-Dynavox-I-16.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:35.021Z","2026-10-16T11:53:35.021Z","Tobii Dynavox I-Series","","","Operating System: Windows",NULL,NULL,"# Tobii Dynavox I-Series\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nThe I-Series is an eye gaze-enabled speech generating device featuring the world’s leading eye tracker. Purpose-built for people with conditions such as cerebral palsy, Rett syndrome or ALS, this Windows-based device is controlled completely with your eyes to communicate and live more independently.\n\nThe I-16 is a custom-built AAC devices that enable communication and independence for people with disabilities via eye control and other access methods.\n\nIt is the lightest, fastest and most durable integrated eye tracking device available and is packed with ground breaking innovations such as a partner window and industry-leading eye tracking performance using Tobii’s latest eye tracking sensor IS5. The partner window is a second screen, located on the back of the device, which mirrors the phrases being typed and enables true face-to-face communication\n\nMore information at https://www.tobiidynavox.com/products/i-series/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** voice-and-speech\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tobii-dynavox-i-series/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_inspiration-10_1792151619418","Inspiration 10","Operating System: Windows","# Inspiration 10\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nInspiration 10 is a visual thinking tool for creating mind maps, concept maps, graphic organizers, outlines and presentations with ease!\n\nThe visual mapping tool makes it easy to quickly capture your ideas and visually organize them to communicate concepts and strengthen understanding.\n\nManufacturer: TechEdology Ltd (https://www.inspiration-at.com/)\n\nInspiration Manuals: https://www.inspiration-at.com/inspiration-for-windows-how-to-videos/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/inspiration-10/","MADA Portal","web","https://at.mada.org.qa/technology/inspiration-10/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Inspiration_10.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Inspiration_10.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:39.418Z","2026-10-16T11:53:39.418Z","Inspiration 10","","","Operating System: Windows",NULL,NULL,"# Inspiration 10\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nInspiration 10 is a visual thinking tool for creating mind maps, concept maps, graphic organizers, outlines and presentations with ease!\n\nThe visual mapping tool makes it easy to quickly capture your ideas and visually organize them to communicate concepts and strengthen understanding.\n\nManufacturer: TechEdology Ltd (https://www.inspiration-at.com/)\n\nInspiration Manuals: https://www.inspiration-at.com/inspiration-for-windows-how-to-videos/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/inspiration-10/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_scanmarker-reader_1792151621626","Scanmarker Reader","Operating System: Other","# Scanmarker Reader\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Scanmarker is a fast and simple way to scan full lines of text straight to your computer. With a processing speed 30 times faster than manual typing, the Scanmarker will let you scan textbooks, notebooks, invoices and magazines, so students, lawyers, researchers or anyone with learning difficulties can read, study or work confidently.\n\nTutorials: https://scanmarkersupport.zendesk.com/hc/en-us/categories/4403283004177-Tutorials\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/scanmarker-reader/","MADA Portal","web","https://at.mada.org.qa/technology/scanmarker-reader/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/scanmarker.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/scanmarker.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:41.626Z","2026-10-16T11:53:41.626Z","Scanmarker Reader","","","Operating System: Other",NULL,NULL,"# Scanmarker Reader\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Scanmarker is a fast and simple way to scan full lines of text straight to your computer. With a processing speed 30 times faster than manual typing, the Scanmarker will let you scan textbooks, notebooks, invoices and magazines, so students, lawyers, researchers or anyone with learning difficulties can read, study or work confidently.\n\nTutorials: https://scanmarkersupport.zendesk.com/hc/en-us/categories/4403283004177-Tutorials\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/scanmarker-reader/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_skwitch_1792151623692","Skwitch","Operating System: iOS","# Skwitch\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nSkwitch is a clever new music-making gadget & app. It clips straight on to your iPhone and uses the onboard sensors to create a one-button musical instrument that is responsive, expressive and amazingly versatile. Just press the button to play notes. It’s that easy.\n\nSkwitch is for anyone looking to build confidence in their musical abilities; from aspiring musicians looking for a fun, portable way to get into music-making, to music technologists looking for ways to bring new life to their compositions and live sets. Skwitch makes it fun and easy to get started and doesn’t require an in-depth understanding of music theory or technique. With Skwitch you can just dive right in.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/skwitch/","MADA Portal","web","https://at.mada.org.qa/technology/skwitch/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Skwitch.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Skwitch.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:43.692Z","2026-10-16T11:53:43.692Z","Skwitch","","","Operating System: iOS",NULL,NULL,"# Skwitch\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nSkwitch is a clever new music-making gadget & app. It clips straight on to your iPhone and uses the onboard sensors to create a one-button musical instrument that is responsive, expressive and amazingly versatile. Just press the button to play notes. It’s that easy.\n\nSkwitch is for anyone looking to build confidence in their musical abilities; from aspiring musicians looking for a fun, portable way to get into music-making, to music technologists looking for ways to bring new life to their compositions and live sets. Skwitch makes it fun and easy to get started and doesn’t require an in-depth understanding of music theory or technique. With Skwitch you can just dive right in.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/skwitch/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_xbox-adaptive-controller_1792151627759","Xbox Adaptive Controller","Operating System: Windows","# Xbox Adaptive Controller\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nXbox Adaptive Controller creates a custom controller experience that makes gaming more accessible. Connect external switches, buttons, mounts and joysticks.\n\nDesigned primarily to meet the needs of gamers with limited mobility, the Xbox Adaptive Controller features large programmable buttons and connects to external switches, buttons, mounts and joysticks to help make gaming more accessible. Requires external devices for gameplay.\n\nManufacturer: Xbox ( https://www.xbox.com/en-US/accessories/controllers/xbox-adaptive-controller)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/xbox-adaptive-controller/","MADA Portal","web","https://at.mada.org.qa/technology/xbox-adaptive-controller/",NULL,"neuromusculoskeletal-movement","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Xbox-accessible-game-controller.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Xbox-accessible-game-controller.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:47.759Z","2026-10-16T11:54:27.111Z","Xbox Adaptive Controller","","","Operating System: Windows",NULL,NULL,"# Xbox Adaptive Controller\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nXbox Adaptive Controller creates a custom controller experience that makes gaming more accessible. Connect external switches, buttons, mounts and joysticks.\n\nDesigned primarily to meet the needs of gamers with limited mobility, the Xbox Adaptive Controller features large programmable buttons and connects to external switches, buttons, mounts and joysticks to help make gaming more accessible. Requires external devices for gameplay.\n\nManufacturer: Xbox ( https://www.xbox.com/en-US/accessories/controllers/xbox-adaptive-controller)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/xbox-adaptive-controller/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_animated-sandbox_1792151629868","Animated SandBox","Operating System: Other","# Animated SandBox\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Animated Sandbox is an educational interactive experience in which users can change and redesign habitats and topography. Users will explore, create, and learn by using their imaginations and our augmented reality sandbox.\n\nUsers will pile up and dig out sand, while an interactive sensor detects the changes made to the sand and the projection adjusts accordingly in real time. Augmented reality layers will make mountains, plains, and bodies of water, teaching users about topography and different environments. Animals and objects will react to the changes and roam where they are found in their natural habitats. This interactive tabletop sandbox is perfect for schools, museums, science centers, and more!\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/animated-sandbox/","MADA Portal","web","https://at.mada.org.qa/technology/animated-sandbox/",NULL,"neuromusculoskeletal-movement","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Sandbox.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Sandbox.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:49.868Z","2026-10-16T11:54:29.071Z","Animated SandBox","","","Operating System: Other",NULL,NULL,"# Animated SandBox\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Animated Sandbox is an educational interactive experience in which users can change and redesign habitats and topography. Users will explore, create, and learn by using their imaginations and our augmented reality sandbox.\n\nUsers will pile up and dig out sand, while an interactive sensor detects the changes made to the sand and the projection adjusts accordingly in real time. Augmented reality layers will make mountains, plains, and bodies of water, teaching users about topography and different environments. Animals and objects will react to the changes and roam where they are found in their natural habitats. This interactive tabletop sandbox is perfect for schools, museums, science centers, and more!\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/animated-sandbox/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_hopspot_1792151632164","Hopspot","Operating System: iOS","# Hopspot\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nHopspots is an interactive learning tool designed to make it easy to create active learning. Hopspots challenges in movement, cognitive training, language learning, collaboration etc., and makes it possible for children to become digital co-creators of learning content when they produce games in the app.\n\nHopspots trains body and memory whilst playing and learning. Thus, Hopspots can be used at all ages. For instance, Hopspots can help 3-year-old children recognize animal sounds, 7-year-old children with learning the alphabet, 10-year-old children with multiplication and division, 15-year-old children with collaboration and discussion, and help elderly citizens with having fun while preventing dementia and other age-related illnesses.\n\nHopspot How-to guides: https://www.hopspots.dk/en/get-started/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/hopspot/","MADA Portal","web","https://at.mada.org.qa/technology/hopspot/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Hopspot.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Hopspot.jpg\"]}",0,NULL,NULL,"2026-10-16T11:53:52.164Z","2026-10-16T11:53:52.164Z","Hopspot","","","Operating System: iOS",NULL,NULL,"# Hopspot\n\n## Mô tả\nOperating System: iOS\n\n## Chi tiết sản phẩm\nHopspots is an interactive learning tool designed to make it easy to create active learning. Hopspots challenges in movement, cognitive training, language learning, collaboration etc., and makes it possible for children to become digital co-creators of learning content when they produce games in the app.\n\nHopspots trains body and memory whilst playing and learning. Thus, Hopspots can be used at all ages. For instance, Hopspots can help 3-year-old children recognize animal sounds, 7-year-old children with learning the alphabet, 10-year-old children with multiplication and division, 15-year-old children with collaboration and discussion, and help elderly citizens with having fun while preventing dementia and other age-related illnesses.\n\nHopspot How-to guides: https://www.hopspots.dk/en/get-started/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/hopspot/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_lego-spike-essential_1792151634202","Lego Learning System","Operating System: Other","# Lego Learning System\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe LEGO® Learning System is a series of solutions that work seamlessly together to deliver engaging, hands-on STEAM learning experiences for students of all ages. It combines standards-aligned curriculum units, stackable LEGO bricks, a simple coding progression, intelligent hardware, and professional development, creating limitless possibilities for playful STEAM learning.\n\nA scalable learning system based on the familiar LEGO brick that is intuitive, inclusive, and adaptable. Learn how it is transforming the way educators teach and kids learn.\n\nFuture-proofs Students with STEAM and 21st Century Skills\nStudents become confident, life-long learners through unlimited possibilities for hands-on, playful STEAM learning.\n\nIt Grows as they Grow\nAbstract concepts become tangible, allowing students to move from simple explorations to increasingly complex real-world challenges as they progress through different grades.\n\nEasy Implementation\nOffers a scalable design, making it easy to implement at the classroom, school, or district level.\n\nManufacturer: Lego Education (https://education.lego.com/en-us/learningsystem#the-lego-learning-system )\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/lego-spike-essential/","MADA Portal","web","https://at.mada.org.qa/technology/lego-spike-essential/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/lego-learning-system.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/lego-learning-system.png\"]}",0,NULL,NULL,"2026-10-16T11:53:54.202Z","2026-10-16T11:53:54.202Z","Lego Learning System","","","Operating System: Other",NULL,NULL,"# Lego Learning System\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe LEGO® Learning System is a series of solutions that work seamlessly together to deliver engaging, hands-on STEAM learning experiences for students of all ages. It combines standards-aligned curriculum units, stackable LEGO bricks, a simple coding progression, intelligent hardware, and professional development, creating limitless possibilities for playful STEAM learning.\n\nA scalable learning system based on the familiar LEGO brick that is intuitive, inclusive, and adaptable. Learn how it is transforming the way educators teach and kids learn.\n\nFuture-proofs Students with STEAM and 21st Century Skills\nStudents become confident, life-long learners through unlimited possibilities for hands-on, playful STEAM learning.\n\nIt Grows as they Grow\nAbstract concepts become tangible, allowing students to move from simple explorations to increasingly complex real-world challenges as they progress through different grades.\n\nEasy Implementation\nOffers a scalable design, making it easy to implement at the classroom, school, or district level.\n\nManufacturer: Lego Education (https://education.lego.com/en-us/learningsystem#the-lego-learning-system )\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/lego-spike-essential/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_mabot_1792151636360","Mabot","Operating System: Other","# Mabot\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nMabot is an AI STEAM toy to let kids build, customize, and program robots, exploring mechanics, engineering, coding, and developing STEAM skills.\n\nMabot integrates complex functions into quality ball modules, so kids can just simply plug and play. Multi-angle design allows numerous combinations and variations so kids can build just about anything they can imagine. In addition, Mabot’s compatibility with Lego toys allows kids to extend their play.\n\nMabot educational resources: https://www.bellrobot.com/education.html\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/mabot/","MADA Portal","web","https://at.mada.org.qa/technology/mabot/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/mabot.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/mabot.png\"]}",0,NULL,NULL,"2026-10-16T11:53:56.360Z","2026-10-16T11:53:56.360Z","Mabot","","","Operating System: Other",NULL,NULL,"# Mabot\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nMabot is an AI STEAM toy to let kids build, customize, and program robots, exploring mechanics, engineering, coding, and developing STEAM skills.\n\nMabot integrates complex functions into quality ball modules, so kids can just simply plug and play. Multi-angle design allows numerous combinations and variations so kids can build just about anything they can imagine. In addition, Mabot’s compatibility with Lego toys allows kids to extend their play.\n\nMabot educational resources: https://www.bellrobot.com/education.html\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/mabot/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_kais-clan_1792151638610","Kai’s Clan","Operating System: Other","# Kai’s Clan\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nKai’s Clan is a collaborative coding platform that encompasses several technologies into an all-in-one learning platform.\n\nTeach coding, robotics, AR, VR, and the Internet of Things (IoT) in one easy-to-use web platform that works seamlessly on just about any device. Students code their robots to navigate the mat in real life, in real-time, wherever they are in the world.  At the same time, their 3D Robot avatars collaborate in a virtual world.\n\nKai’s Clan User Guide: https://kaisclan.ai/support/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/kais-clan/","MADA Portal","web","https://at.mada.org.qa/technology/kais-clan/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/kais-clan.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/kais-clan.png\"]}",0,NULL,NULL,"2026-10-16T11:53:58.611Z","2026-10-16T11:53:58.611Z","Kai’s Clan","","","Operating System: Other",NULL,NULL,"# Kai’s Clan\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nKai’s Clan is a collaborative coding platform that encompasses several technologies into an all-in-one learning platform.\n\nTeach coding, robotics, AR, VR, and the Internet of Things (IoT) in one easy-to-use web platform that works seamlessly on just about any device. Students code their robots to navigate the mat in real life, in real-time, wherever they are in the world.  At the same time, their 3D Robot avatars collaborate in a virtual world.\n\nKai’s Clan User Guide: https://kaisclan.ai/support/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/kais-clan/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_amazon-alexa-app_1792151640824","Amazon Alexa","Operating System: Other","# Amazon Alexa\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nUse the Amazon Alexa App to set up your Alexa-enabled devices, listen to music, create shopping lists, get news updates, and much more. The more you use Alexa, the more she adapts to your voice, vocabulary, and personal preferences.\n\nShow and Tell is designed to help people who are blind or have low vision. Show and Tell identifies common grocery items and other products by using your Echo Show’s camera. Hold up a product such as a canned good in front of your Echo Show’s camera and say, “Alexa, what am I holding?“\n\nAmazon announces accessibility upgrades to Alexa app for people with vision impairments.\n\nLight and dark modes: Using their mobile device settings, users can choose between light and dark modes for benefits like increased readability and colour contrast. Dark mode will offer benefits such as screen viewing comfort in low-light environments and improved device battery life, while light mode will offer better readability and colour contrast that stands out in high-light environments. The Alexa app will default to light or dark mode, depending on the user’s mobile settings.\nText scaling for improved accessibility: Users can set their device’s font size to be larger than the standard size. This means the individual will see larger text on most screens of the Alexa app proportional to their preferred accessibility setting. This can be especially helpful for people with certain vision impairments.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/amazon-alexa-app/","MADA Portal","web","https://at.mada.org.qa/technology/amazon-alexa-app/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Amazon-Alexa.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/Amazon-Alexa.png\"]}",0,NULL,NULL,"2026-10-16T11:54:00.825Z","2026-10-16T11:54:00.825Z","Amazon Alexa","","","Operating System: Other",NULL,NULL,"# Amazon Alexa\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nUse the Amazon Alexa App to set up your Alexa-enabled devices, listen to music, create shopping lists, get news updates, and much more. The more you use Alexa, the more she adapts to your voice, vocabulary, and personal preferences.\n\nShow and Tell is designed to help people who are blind or have low vision. Show and Tell identifies common grocery items and other products by using your Echo Show’s camera. Hold up a product such as a canned good in front of your Echo Show’s camera and say, “Alexa, what am I holding?“\n\nAmazon announces accessibility upgrades to Alexa app for people with vision impairments.\n\nLight and dark modes: Using their mobile device settings, users can choose between light and dark modes for benefits like increased readability and colour contrast. Dark mode will offer benefits such as screen viewing comfort in low-light environments and improved device battery life, while light mode will offer better readability and colour contrast that stands out in high-light environments. The Alexa app will default to light or dark mode, depending on the user’s mobile settings.\nText scaling for improved accessibility: Users can set their device’s font size to be larger than the standard size. This means the individual will see larger text on most screens of the Alexa app proportional to their preferred accessibility setting. This can be especially helpful for people with certain vision impairments.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/amazon-alexa-app/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_orcam-read_1792151643186","OrCam Read","Operating System: Other","# OrCam Read\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nFor people with mild low vision, reading fatigue, reading difficulties including dyslexia, and for anyone who consumes large amounts of text. OrCam Read is a first-of-its-kind handheld device with a smart camera that seamlessly reads text from any printed surface or digital screen. Enjoy the morning paper, read any book, and even read all that appears on your computer or smartphone screen.\n\nOrCam Read User Guide and Tutorial: https://www.orcam.com/en/read-user-area/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/orcam-read/","MADA Portal","web","https://at.mada.org.qa/technology/orcam-read/",NULL,"mental-cognitive","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/OrCam-Read.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/OrCam-Read.png\"]}",0,NULL,NULL,"2026-10-16T11:54:03.186Z","2026-10-16T11:54:03.186Z","OrCam Read","","","Operating System: Other",NULL,NULL,"# OrCam Read\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nFor people with mild low vision, reading fatigue, reading difficulties including dyslexia, and for anyone who consumes large amounts of text. OrCam Read is a first-of-its-kind handheld device with a smart camera that seamlessly reads text from any printed surface or digital screen. Enjoy the morning paper, read any book, and even read all that appears on your computer or smartphone screen.\n\nOrCam Read User Guide and Tutorial: https://www.orcam.com/en/read-user-area/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mental-cognitive\n\n## Nguồn\nhttps://at.mada.org.qa/technology/orcam-read/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_mogo-super-evaluation-kit_1792151646941","MOGO Super Evaluation Kit","Operating System: Other","# MOGO Super Evaluation Kit\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nMogo Super Evaluation Kit offers virtually every Mogo item to fully test different configurations to see what works best for wheelchair mounts and accessories. Featuring a sample of the three arms; modular metal, flexible steel, and modular plastic, plus a handful of bases and accessories.\n\nManufacturer: Adaptive Tech Solutions Modular Hose MOGO DIY Mounting Super Kit. Save money by purchasing kits from Adaptive Tech Solutions.\n\nVideo: Master Guide to ModularHose & MOGO Mounts Adaptive Technology Mounting Solutions\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/mogo-super-evaluation-kit/","MADA Portal","web","https://at.mada.org.qa/technology/mogo-super-evaluation-kit/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-105342.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/Screenshot-2025-02-13-105342.png\"]}",0,NULL,NULL,"2026-10-16T11:54:06.941Z","2026-10-16T11:54:32.612Z","MOGO Super Evaluation Kit","","","Operating System: Other",NULL,NULL,"# MOGO Super Evaluation Kit\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nMogo Super Evaluation Kit offers virtually every Mogo item to fully test different configurations to see what works best for wheelchair mounts and accessories. Featuring a sample of the three arms; modular metal, flexible steel, and modular plastic, plus a handful of bases and accessories.\n\nManufacturer: Adaptive Tech Solutions Modular Hose MOGO DIY Mounting Super Kit. Save money by purchasing kits from Adaptive Tech Solutions.\n\nVideo: Master Guide to ModularHose & MOGO Mounts Adaptive Technology Mounting Solutions\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/mogo-super-evaluation-kit/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_assessment-switch-kit_1792151648964","Assessment Switch Kit","Operating System: Other","# Assessment Switch Kit\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Assessment Switch Kit is a comprehensive, bespoke package designed for users with limited motor control, providing a diverse selection of highly sensitive switches that require zero to minimal pressure for activation. This kit allows educators, therapists, and caregivers to assess and determine the most suitable switch options for individual users, ensuring optimal accessibility and comfort.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/assessment-switch-kit/","MADA Portal","web","https://at.mada.org.qa/technology/assessment-switch-kit/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/assessment-switch-kit-catalogue-2021.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2025/02/assessment-switch-kit-catalogue-2021.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:08.964Z","2026-10-16T11:54:34.690Z","Assessment Switch Kit","","","Operating System: Other",NULL,NULL,"# Assessment Switch Kit\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe Assessment Switch Kit is a comprehensive, bespoke package designed for users with limited motor control, providing a diverse selection of highly sensitive switches that require zero to minimal pressure for activation. This kit allows educators, therapists, and caregivers to assess and determine the most suitable switch options for individual users, ensuring optimal accessibility and comfort.\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/assessment-switch-kit/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_tobii-pceye-5_1792151650982","Tobii PCEye 5","Operating System: Other","# Tobii PCEye 5\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nPCEye 5 is a compact eye tracker that enables people with physical disabilities to control a Windows computer with their eyes.\nReplace a traditional keyboard and mouse with your eyes and surf the web, connect on social media, play games, create documents and more. Simply connect the PCEye to your Windows device via USB, and access everything your computer has to offer, intuitively and independently with TD Control.\n\nManufacturer: TobiiDynavox (https://www.tobiidynavox.com)\n\nSupport Manuals: https://www.tobiidynavox.com/pages/pceye-product-support\nhttps://www.tobiidynavox.com/pages/pceye-product-support?tab=1\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tobii-pceye-5/","MADA Portal","web","https://at.mada.org.qa/technology/tobii-pceye-5/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Tobii-PCEye-5.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Tobii-PCEye-5.png\"]}",0,NULL,NULL,"2026-10-16T11:54:10.982Z","2026-10-16T11:54:36.751Z","Tobii PCEye 5","","","Operating System: Other",NULL,NULL,"# Tobii PCEye 5\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nPCEye 5 is a compact eye tracker that enables people with physical disabilities to control a Windows computer with their eyes.\nReplace a traditional keyboard and mouse with your eyes and surf the web, connect on social media, play games, create documents and more. Simply connect the PCEye to your Windows device via USB, and access everything your computer has to offer, intuitively and independently with TD Control.\n\nManufacturer: TobiiDynavox (https://www.tobiidynavox.com)\n\nSupport Manuals: https://www.tobiidynavox.com/pages/pceye-product-support\nhttps://www.tobiidynavox.com/pages/pceye-product-support?tab=1\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/tobii-pceye-5/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_sesame-enable-touch-free-control_1792151653079","Sesame Enable touch free control","Operating System: Windows, iOS, Android","# Sesame Enable touch free control\n\n## Mô tả\nOperating System: Windows, iOS, Android\n\n## Chi tiết sản phẩm\nSesame Enable created hands free, head control access for smartphones, tablets and computers. These solutions are used daily by those living with ALS, Spinal Cord Injuries, Multiple Sclerosis and other conditions leading to paralysis.\n\nManufacturer: Sesame Enable (https://www.sesame-enable.com/)\n\nDownload Sesame Enable: https://www.sesame-enable.com/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/sesame-enable-touch-free-control/","MADA Portal","web","https://at.mada.org.qa/technology/sesame-enable-touch-free-control/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/sesame-enable.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/sesame-enable.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:13.080Z","2026-10-16T11:54:39.653Z","Sesame Enable touch free control","","","Operating System: Windows, iOS, Android",NULL,NULL,"# Sesame Enable touch free control\n\n## Mô tả\nOperating System: Windows, iOS, Android\n\n## Chi tiết sản phẩm\nSesame Enable created hands free, head control access for smartphones, tablets and computers. These solutions are used daily by those living with ALS, Spinal Cord Injuries, Multiple Sclerosis and other conditions leading to paralysis.\n\nManufacturer: Sesame Enable (https://www.sesame-enable.com/)\n\nDownload Sesame Enable: https://www.sesame-enable.com/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/sesame-enable-touch-free-control/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_quha-zono-2_1792151655065","Quha Zono 2","Operating System: Other","# Quha Zono 2\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nQuha Zono 2 is a wireless handsfree mouse operated with head movements. It detects motion and transforms it into intuitive onscreen cursor movement. Quha Zono 2 is an improved version of the Quha Zono mouse including all its features and a number of new ones.\n\nManufacturer: Quha https://www.quha.com/products/quha-zono-2/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/quha-zono-2/","MADA Portal","web","https://at.mada.org.qa/technology/quha-zono-2/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Quha-Zono-2.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/Quha-Zono-2.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:15.065Z","2026-10-16T11:54:41.782Z","Quha Zono 2","","","Operating System: Other",NULL,NULL,"# Quha Zono 2\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nQuha Zono 2 is a wireless handsfree mouse operated with head movements. It detects motion and transforms it into intuitive onscreen cursor movement. Quha Zono 2 is an improved version of the Quha Zono mouse including all its features and a number of new ones.\n\nManufacturer: Quha https://www.quha.com/products/quha-zono-2/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/quha-zono-2/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_amaneo-assistive-mouse-adapter_1792151657003","AMAneo Assistive Mouse Adapter","Operating System: Other","# AMAneo Assistive Mouse Adapter\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe AMAneo Anti-Tremor Assistive Mouse Adapter enables people with a hand tremor to use a computer mouse. It electronically filters the trembling of the hand, which can be very strong, so that the mouse pointer on the display moves smoothly. With tablets, touchscreen control is replaced by a normal mouse or an alternative mouse such as one offering head or chin control. Not all mice function within the power rating of the AMAneo USB so we now also include a free Logitech wireless mouse to ensure compatibility.\n\nSupport Document: https://www.csslabs.de/downloads/CSS_Produktuebersicht_AMAneo_DE_V10-21.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/amaneo-assistive-mouse-adapter/","MADA Portal","web","https://at.mada.org.qa/technology/amaneo-assistive-mouse-adapter/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/amaneo-usb.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/12/amaneo-usb.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:17.003Z","2026-10-16T11:54:43.777Z","AMAneo Assistive Mouse Adapter","","","Operating System: Other",NULL,NULL,"# AMAneo Assistive Mouse Adapter\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nThe AMAneo Anti-Tremor Assistive Mouse Adapter enables people with a hand tremor to use a computer mouse. It electronically filters the trembling of the hand, which can be very strong, so that the mouse pointer on the display moves smoothly. With tablets, touchscreen control is replaced by a normal mouse or an alternative mouse such as one offering head or chin control. Not all mice function within the power rating of the AMAneo USB so we now also include a free Logitech wireless mouse to ensure compatibility.\n\nSupport Document: https://www.csslabs.de/downloads/CSS_Produktuebersicht_AMAneo_DE_V10-21.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/amaneo-assistive-mouse-adapter/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_open-sesame-app_1792151659000","Open Sesame App","Operating System: Windows, iOS, Android","# Open Sesame App\n\n## Mô tả\nOperating System: Windows, iOS, Android\n\n## Chi tiết sản phẩm\nSesame Enable created hands free, head control access for smartphones, tablets and computers. These solutions are used daily by those living with ALS, Spinal Cord Injuries, Multiple Sclerosis and other conditions leading to paralysis.\n\nManufacturer: Sesame Enable (https://www.sesame-enable.com/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/open-sesame-app/","MADA Portal","web","https://at.mada.org.qa/technology/open-sesame-app/",NULL,"neuromusculoskeletal-movement","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/Sesame-Enable-App.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2022/06/Sesame-Enable-App.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:19.001Z","2026-10-16T11:54:19.001Z","Open Sesame App","","","Operating System: Windows, iOS, Android",NULL,NULL,"# Open Sesame App\n\n## Mô tả\nOperating System: Windows, iOS, Android\n\n## Chi tiết sản phẩm\nSesame Enable created hands free, head control access for smartphones, tablets and computers. These solutions are used daily by those living with ALS, Spinal Cord Injuries, Multiple Sclerosis and other conditions leading to paralysis.\n\nManufacturer: Sesame Enable (https://www.sesame-enable.com/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/open-sesame-app/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_soundbeam-6_1792151663400","SoundBeam 6","Operating System: Other","# SoundBeam 6\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nSoundBeam 6 is a touch free device that uses sensor technology to translate movement into music and sound. It gives children and adults the opportunity, regardless of their impairments or disability, to play music.\n\nMore about SoundBeam 6: https://www.soundbeam.co.uk/soundbeam-6-product-page\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/soundbeam-6/","MADA Portal","web","https://at.mada.org.qa/technology/soundbeam-6/",NULL,"neuromusculoskeletal-movement","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/SoundBeam-6.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/SoundBeam-6.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:23.400Z","2026-10-16T11:54:23.400Z","SoundBeam 6","","","Operating System: Other",NULL,NULL,"# SoundBeam 6\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\nSoundBeam 6 is a touch free device that uses sensor technology to translate movement into music and sound. It gives children and adults the opportunity, regardless of their impairments or disability, to play music.\n\nMore about SoundBeam 6: https://www.soundbeam.co.uk/soundbeam-6-product-page\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/soundbeam-6/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_1-2-switch_1792151665271","1-2-Switch","Operating System: Other","# 1-2-Switch\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\n1-2 Switch is a multiplayer party game that launched with the Nintendo Switch console. The game makes heavy use of the Switch’s Joy-Con motion controllers for its minigames, making it ideal for physiotherapy.\n\nManufacturer: Nintendo (https://www.nintendo.com/store/products/1-2-switch-switch/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/1-2-switch/","MADA Portal","web","https://at.mada.org.qa/technology/1-2-switch/",NULL,"neuromusculoskeletal-movement","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/1-2-switch-switch.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/1-2-switch-switch.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:25.271Z","2026-10-16T11:54:25.271Z","1-2-Switch","","","Operating System: Other",NULL,NULL,"# 1-2-Switch\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\n1-2 Switch is a multiplayer party game that launched with the Nintendo Switch console. The game makes heavy use of the Switch’s Joy-Con motion controllers for its minigames, making it ideal for physiotherapy.\n\nManufacturer: Nintendo (https://www.nintendo.com/store/products/1-2-switch-switch/)\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** neuromusculoskeletal-movement\n\n## Nguồn\nhttps://at.mada.org.qa/technology/1-2-switch/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_esight-4_1792151686027","eSight 4","Operating System: Other","# eSight 4\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\neSight 4 takes sight enhancement to a new level. Experience best visual acuity, unmatched mobility, ease of use, and new mobile and cloud-based capabilities.\n\neSight’s low vision device, more commonly referred to as electronic eyewear, functions by stimulating synaptic activity from the remaining photoreceptor function of the user’s eyes. Using a cutting edge camera, smart algorithms, and high-resolution screens, the assistive technology maximizes the visual information provided to the brain to naturally compensate for gaps in the user’s field of view.\n\nManufacturer: eSight Corp. (https://esighteyewear.com/low-vision-device-for-visually-impaired/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/esight-4/","MADA Portal","web","https://at.mada.org.qa/technology/esight-4/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/eSight.jpg\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/eSight.jpg\"]}",0,NULL,NULL,"2026-10-16T11:54:46.027Z","2026-10-16T11:54:46.027Z","eSight 4","","","Operating System: Other",NULL,NULL,"# eSight 4\n\n## Mô tả\nOperating System: Other\n\n## Chi tiết sản phẩm\neSight 4 takes sight enhancement to a new level. Experience best visual acuity, unmatched mobility, ease of use, and new mobile and cloud-based capabilities.\n\neSight’s low vision device, more commonly referred to as electronic eyewear, functions by stimulating synaptic activity from the remaining photoreceptor function of the user’s eyes. Using a cutting edge camera, smart algorithms, and high-resolution screens, the assistive technology maximizes the visual information provided to the brain to naturally compensate for gaps in the user’s field of view.\n\nManufacturer: eSight Corp. (https://esighteyewear.com/low-vision-device-for-visually-impaired/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/esight-4/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_lazarillo_1792151688204","Lazarillo","Operating System: iOS, Android","# Lazarillo\n\n## Mô tả\nOperating System: iOS, Android\n\n## Chi tiết sản phẩm\nLazarillo is an Autonomous guidance Application for smart devices primarily used by people with visual impairment. Through voice messages it allows user to know the current location and nearby services provided, giving the right information regarding bus stations, cafes, banks, restaurants, street intersections, etc.\n\nLazarillo App user support: https://lazarillo.app/usersupport/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/lazarillo/","MADA Portal","web","https://at.mada.org.qa/technology/lazarillo/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/lazarillo-app.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/10/lazarillo-app.png\"]}",0,NULL,NULL,"2026-10-16T11:54:48.204Z","2026-10-16T11:54:48.204Z","Lazarillo","","","Operating System: iOS, Android",NULL,NULL,"# Lazarillo\n\n## Mô tả\nOperating System: iOS, Android\n\n## Chi tiết sản phẩm\nLazarillo is an Autonomous guidance Application for smart devices primarily used by people with visual impairment. Through voice messages it allows user to know the current location and nearby services provided, giving the right information regarding bus stations, cafes, banks, restaurants, street intersections, etc.\n\nLazarillo App user support: https://lazarillo.app/usersupport/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/lazarillo/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_quha-dwell_1792151690303","Quha Dwell","Operating System: Windows","# Quha Dwell\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nQuha Dwell is a complete computer access software for assistive mice.\nThe unique Instant Dwell feature makes Windows computer usage faster, more comfortable and ergonomic compared to any current dwell control software.\nWith Quha Dwell you can easily control all the functions of your computer, switch between applications, copy-paste and scroll. Any new function can be added to Quha Dwell to meet your needs.\nQuha Dwell includes an on-screen-keyboard with word prediction.\n\nDownload: https://www.quha.com/support-2/downloads/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/quha-dwell/","MADA Portal","web","https://at.mada.org.qa/technology/quha-dwell/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Quha-Dwell.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Quha-Dwell.png\"]}",0,NULL,NULL,"2026-10-16T11:54:50.304Z","2026-10-16T11:54:50.304Z","Quha Dwell","","","Operating System: Windows",NULL,NULL,"# Quha Dwell\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nQuha Dwell is a complete computer access software for assistive mice.\nThe unique Instant Dwell feature makes Windows computer usage faster, more comfortable and ergonomic compared to any current dwell control software.\nWith Quha Dwell you can easily control all the functions of your computer, switch between applications, copy-paste and scroll. Any new function can be added to Quha Dwell to meet your needs.\nQuha Dwell includes an on-screen-keyboard with word prediction.\n\nDownload: https://www.quha.com/support-2/downloads/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/quha-dwell/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_dwell-clicker-2_1792151692450","Dwell Clicker 2","Operating System: Windows","# Dwell Clicker 2\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nDwell Clicker 2 is a Windows application that allows you to use a mouse or other pointing device without clicking buttons. It is ideal for people with RSI and people who use alternative pointing devices such as a headpointer or joystick.\n\nDwell Clicker 2 User Guide: https://thinksmartbox.com/product/dwell-clicker/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/dwell-clicker-2/","MADA Portal","web","https://at.mada.org.qa/technology/dwell-clicker-2/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Dwell-Clicker-2.gif\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Dwell-Clicker-2.gif\"]}",0,NULL,NULL,"2026-10-16T11:54:52.450Z","2026-10-16T11:54:52.450Z","Dwell Clicker 2","","","Operating System: Windows",NULL,NULL,"# Dwell Clicker 2\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nDwell Clicker 2 is a Windows application that allows you to use a mouse or other pointing device without clicking buttons. It is ideal for people with RSI and people who use alternative pointing devices such as a headpointer or joystick.\n\nDwell Clicker 2 User Guide: https://thinksmartbox.com/product/dwell-clicker/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/dwell-clicker-2/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_smyle-mouse_1792151694834","Smyle Mouse","Operating System: Windows","# Smyle Mouse\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nSmyle Mouse is a head mouse software for hands-free control via head motions & face gestures. Patented head-based mouse control via web camera.\n\nSmyle Mouse is suitable for users with acquired and progressive conditions that limit movement, such as muscular dystrophy, spinal cord injury or MND/ALS.\n\nSmyle Mouse does not require you to be positioned at a certain distance from the screen and can be programmed to detect even the slightest head movements.\n\nManufacturer: Perceptive Devices LLC (https://smylemouse.com/)\n\nSmyle Mouse User guide and tutorial: https://smylemouse.com/resources/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/smyle-mouse/","MADA Portal","web","https://at.mada.org.qa/technology/smyle-mouse/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/smyle-mouse.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/smyle-mouse.png\"]}",0,NULL,NULL,"2026-10-16T11:54:54.834Z","2026-10-16T11:54:54.834Z","Smyle Mouse","","","Operating System: Windows",NULL,NULL,"# Smyle Mouse\n\n## Mô tả\nOperating System: Windows\n\n## Chi tiết sản phẩm\nSmyle Mouse is a head mouse software for hands-free control via head motions & face gestures. Patented head-based mouse control via web camera.\n\nSmyle Mouse is suitable for users with acquired and progressive conditions that limit movement, such as muscular dystrophy, spinal cord injury or MND/ALS.\n\nSmyle Mouse does not require you to be positioned at a certain distance from the screen and can be programmed to detect even the slightest head movements.\n\nManufacturer: Perceptive Devices LLC (https://smylemouse.com/)\n\nSmyle Mouse User guide and tutorial: https://smylemouse.com/resources/\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/smyle-mouse/","","",0);
INSERT OR REPLACE INTO knowledge_items (id,title,description,content,source,source_type,url,file_path,category,iso_codes,wcag_level,who_gate_area,auto_classified,confidence,status,chunk_count,language,metadata,indexed,indexed_at,created_by,created_at,updated_at,title_en,title_ar,title_fr,description_en,description_ar,description_fr,content_en,content_ar,content_fr,translated) VALUES ("kbprod_dragon-professional_1792151697075","Dragon Professional","Operating System: Windows, iOS, Chrome","# Dragon Professional\n\n## Mô tả\nOperating System: Windows, iOS, Chrome\n\n## Chi tiết sản phẩm\nNuance® Dragon® Professional Individual expands the boundaries of speech recognition technology for documentation productivity on the PC. With dictation and transcription capabilities that are faster and more accurate than ever before, you’ll spend less time on paperwork and more time on activities that boost the bottom line.\n\nManufacturer: Nuance (now Microsoft for Healthcare)\nDragon Individual User Guide: https://www.nuance.com/content/dam/nuance/en_us/collateral/dragon/guide/gd-dragon-individual-client-install-guide-v15.6-en-us.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/dragon-professional/","MADA Portal","web","https://at.mada.org.qa/technology/dragon-professional/",NULL,"mobility-and-transportation","[]",NULL,NULL,0,0,"published",0,"vi","{\"image_url\":\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Dragon-Professional.png\",\"additional_images\":[\"https://cdn.at.mada.org.qa/data/wp-content/uploads/2021/09/Dragon-Professional.png\"]}",0,NULL,NULL,"2026-10-16T11:54:57.075Z","2026-10-16T11:54:57.075Z","Dragon Professional","","","Operating System: Windows, iOS, Chrome",NULL,NULL,"# Dragon Professional\n\n## Mô tả\nOperating System: Windows, iOS, Chrome\n\n## Chi tiết sản phẩm\nNuance® Dragon® Professional Individual expands the boundaries of speech recognition technology for documentation productivity on the PC. With dictation and transcription capabilities that are faster and more accurate than ever before, you’ll spend less time on paperwork and more time on activities that boost the bottom line.\n\nManufacturer: Nuance (now Microsoft for Healthcare)\nDragon Individual User Guide: https://www.nuance.com/content/dam/nuance/en_us/collateral/dragon/guide/gd-dragon-individual-client-install-guide-v15.6-en-us.pdf\n\n\n\n## Thông tin kỹ thuật\n- **Hãng sản xuất:** Không có thông tin\n- **Mã ISO:** Không có thông tin\n- **Danh mục:** mobility-and-transportation\n\n## Nguồn\nhttps://at.mada.org.qa/technology/dragon-professional/","","",0);
